/**
 * T7 — Integration + concurrent-coexistence parity tests
 *       (standalone-executor-hardening feature)
 *
 * Proves the feature's load-bearing requirements without real Docker or Redis.
 * All Redis interactions use an in-memory fake; the broker uses InMemoryBrokerAdapter
 * (the same in-process implementation used by the local-subprocess profile).
 *
 * Scenario coverage
 * ─────────────────
 *   A. Decoupled flow (orchestrator side)
 *      QueueDispatchAdapter.submit():
 *        1. Registers handle+nonce with the broker BEFORE XADDing.
 *        2. XADDs a credential-free DispatchJob to the dispatch stream.
 *        3. A simulated runner posts a callback; the broker drains it.
 *        4. ack() delegates to broker.ack() and clears the registry.
 *
 *   B. Concurrent coexistence — two profile instances side by side
 *      A bundled (local-subprocess-style) InMemoryBrokerAdapter and a
 *      standalone (local-docker-style) QueueDispatchAdapter operate with
 *      independent handle-spaces, Redis clients, and broker ports.
 *      Submitting to one profile does not affect the other.
 *
 *   C. No credentials in the dispatch stream
 *      The DispatchJob written to the stream must not contain sshPrivateKey
 *      or githubToken — the dispatcher is the sole credential holder.
 *
 *   D. Reconciler: lost dispatch → re-enqueue ≤ N → blocked
 *      A task with an expired execution_handle and no dispatcher alive is
 *      detected and re-enqueued. After MAX_RETRIES exhausted it transitions
 *      to blocked (dispatch_reconciler_max_retries).
 *
 *   E. Unprivileged orchestrator assertion
 *      The local-docker profile bundle (createLocalDockerProfile) exposes
 *      only QueueDispatchAdapter (XADD only) as its executor — it does NOT
 *      expose DockerRunAdapter or any direct-spawn capability.
 *
 * See also:
 *   dispatcher/tests/consumer.test.ts — unit tests for DispatchStreamConsumer
 *     (spawn lock, XAUTOCLAIM redelivery, DLQ routing, cap enforcement).
 *   dispatcher/tests/dispatcher-integration.test.ts — end-to-end dispatcher
 *     hazard tests (crash→redelivery, M:N slow spawn, full pipe with callback).
 *   executors/{claude,hermes}/src/flush-log.test.ts — LOG_SINK gating unit tests.
 */

import {
  describe,
  it,
  expect,
  beforeEach,
  afterEach,
} from "vitest";
import { randomUUID } from "node:crypto";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  rmSync,
  readFileSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { stringify as yamlStringify, parse as yamlParse } from "yaml";
import http from "node:http";

import { InMemoryBrokerAdapter } from "../../src/broker/in-memory.js";
import { QueueDispatchAdapter } from "../../src/executor/queue-dispatch.js";
import { createLocalDockerProfile } from "../../src/profiles/local-docker.js";
import { runDispatchReconciler } from "../../src/loop/dispatch-reconciler.js";
import { DISPATCH_STREAM_KEY } from "@workflow/runtime-abi";
import type { DispatchJob } from "@workflow/runtime-abi";
import type { Task } from "../../src/task/types.js";

// ── In-memory fake Redis ──────────────────────────────────────────────────────
// Minimal fake that supports xAdd and the subset of methods QueueDispatchAdapter
// actually calls.  It does NOT implement XREADGROUP — the dispatcher side is
// tested separately in dispatcher/tests/.

interface FakeStreamEntry {
  id: string;
  fields: Record<string, string>;
}

class FakeRedisClient {
  readonly streams = new Map<string, FakeStreamEntry[]>();
  readonly sets = new Map<string, string>();
  connected = false;

  async connect(): Promise<void> {
    this.connected = true;
  }

  async quit(): Promise<void> {
    this.connected = false;
  }

  async xAdd(
    key: string,
    _id: string,
    fields: Record<string, string>,
  ): Promise<string> {
    const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const entries = this.streams.get(key) ?? [];
    entries.push({ id, fields });
    this.streams.set(key, entries);
    return id;
  }

  lastEntry(streamKey: string): FakeStreamEntry | undefined {
    const entries = this.streams.get(streamKey) ?? [];
    return entries[entries.length - 1];
  }

  allEntries(streamKey: string): FakeStreamEntry[] {
    return this.streams.get(streamKey) ?? [];
  }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeTmpDir(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  tmpDirs.push(dir);
  return dir;
}

afterEach(() => {
  for (const d of tmpDirs) {
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  tmpDirs.length = 0;
});

/** Post a simulated runner callback to the given broker URL. */
function postCallback(
  callbackUrl: string,
  handle: string,
  nonce: string,
  terminalStatus: string,
): Promise<void> {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({
      handle,
      nonce,
      result: { terminal_status: terminalStatus, pr_url: "https://github.com/org/repo/pull/99" },
    });
    const url = new URL(callbackUrl);
    const req = http.request(
      {
        hostname: url.hostname,
        port: Number(url.port),
        path: url.pathname,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
        },
      },
      (res) => { res.resume(); resolve(); },
    );
    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

/** Drain up to `count` completions from broker within `timeoutMs`. */
async function drainN(
  broker: InMemoryBrokerAdapter,
  count: number,
  timeoutMs = 5_000,
): Promise<string[]> {
  const drained: string[] = [];
  const deadline = Date.now() + timeoutMs;
  while (drained.length < count && Date.now() < deadline) {
    const items = await broker.listCompleted({ max: count, lockMs: 5_000 });
    for (const item of items) {
      await broker.ack(item.handle);
      drained.push(item.handle);
    }
    if (drained.length < count) {
      await new Promise((r) => setTimeout(r, 50));
    }
  }
  return drained;
}

function makeInput(handle: string, callbackUrl: string, nonce: string, taskId: string) {
  return {
    taskId,
    featureId: "standalone-executor-hardening",
    workspaceId: "ws-test",
    handle,
    taskRepoUrl: "git@github.com:org/repo.git",
    taskRepoBranch: `feature/standalone-executor-hardening-${taskId}`,
    taskBaseBranch: "feature/standalone-executor-hardening",
    taskRepoBaseBranch: "main",
    mgmtRepoUrl: "git@github.com:org/workspace.git",
    callbackUrl,
    nonce,
    sshPrivateKey: "FAKE_SSH_KEY",
    githubToken: "FAKE_GH_TOKEN",
  };
}

// ── Workspace builder for reconciler tests ───────────────────────────────────

function makeWorkspace(
  wsRoot: string,
  featureId: string,
  task: Partial<Task> & { id: string },
): string {
  const tasksDir = join(wsRoot, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });

  writeFileSync(
    join(wsRoot, "workspace.yaml"),
    yamlStringify({
      workspace_id: "test-ws",
      management_repo: "mgmt",
      repos: [
        {
          id: "workflow",
          github: "git@github.com:org/impl.git",
          base_branch: "main",
        },
        {
          id: "mgmt",
          github: "git@github.com:org/mgmt.git",
          base_branch: "main",
        },
      ],
    }),
    "utf-8",
  );

  const fullTask: Task = {
    id: task.id,
    title: task.title ?? "Test Task",
    repo: task.repo ?? "workflow",
    status: task.status ?? "in_progress",
    depends_on: task.depends_on ?? [],
    blocked_reason: task.blocked_reason ?? null,
    blocked_context: task.blocked_context ?? null,
    branch: task.branch ?? `feature/test-${task.id}`,
    execution: task.execution ?? {
      actor_type: "agent",
      last_updated_by: "test@test.com",
      last_updated_at: new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString(), // 3h ago
    },
    execution_handle: task.execution_handle,
    pr: task.pr ?? { url: "", status: "not_created" },
    workspace_pr: task.workspace_pr ?? null,
    log: task.log ?? [],
  };

  const taskPath = join(tasksDir, `${task.id}.yaml`);
  writeFileSync(taskPath, yamlStringify(fullTask), "utf-8");
  return taskPath;
}

// ── A. Decoupled flow (orchestrator side) ─────────────────────────────────────

describe("A. Decoupled flow — orchestrator side", () => {
  let broker: InMemoryBrokerAdapter;
  let callbackUrl: string;

  beforeEach(async () => {
    broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    await broker.start();
    callbackUrl = broker.getCallbackUrl()!;
  });

  afterEach(async () => {
    await broker.stop();
  });

  it("submit() registers handle+nonce with broker BEFORE XADDing to the stream", async () => {
    const redis = new FakeRedisClient();
    redis.connected = true;

    const adapter = new QueueDispatchAdapter({
      redisClient: redis as never,
      broker,
    });

    const handle = randomUUID();
    const nonce = randomUUID();
    const taskId = "T7-dec-A1";

    await adapter.submit(makeInput(handle, callbackUrl, nonce, taskId));

    // Broker registry must have the handle registered.
    expect(broker.registrySize()).toBe(1);

    // Stream must have exactly one entry.
    const entries = redis.allEntries(DISPATCH_STREAM_KEY);
    expect(entries).toHaveLength(1);
  });

  it("XADDs a credential-free DispatchJob: no sshPrivateKey, no githubToken", async () => {
    const redis = new FakeRedisClient();
    redis.connected = true;

    const adapter = new QueueDispatchAdapter({
      redisClient: redis as never,
      broker,
    });

    const handle = randomUUID();
    const nonce = randomUUID();
    await adapter.submit(makeInput(handle, callbackUrl, nonce, "T7-dec-A2"));

    const entry = redis.lastEntry(DISPATCH_STREAM_KEY)!;
    expect(entry).toBeDefined();

    // Stream stores fields as flat string key/value pairs (not a nested 'job' JSON blob
    // for QueueDispatchAdapter — it uses flat XADD fields).
    const fieldNames = Object.keys(entry.fields);
    expect(fieldNames).not.toContain("sshPrivateKey");
    expect(fieldNames).not.toContain("ssh_private_key");
    expect(fieldNames).not.toContain("githubToken");
    expect(fieldNames).not.toContain("github_token");

    // Core identity fields must be present.
    expect(entry.fields.handle).toBe(handle);
    expect(entry.fields.nonce).toBe(nonce);
    expect(entry.fields.task_id).toBe("T7-dec-A2");
  });

  it("simulated runner callback → broker drains exactly one completion for the handle", async () => {
    const redis = new FakeRedisClient();
    redis.connected = true;

    const adapter = new QueueDispatchAdapter({
      redisClient: redis as never,
      broker,
    });

    const handle = randomUUID();
    const nonce = randomUUID();
    await adapter.submit(makeInput(handle, callbackUrl, nonce, "T7-dec-A3"));

    // Simulate: dispatcher spawns executor, runner posts callback.
    await postCallback(callbackUrl, handle, nonce, "in_review");

    // Orchestrator drains the completion.
    const drained = await drainN(broker, 1, 5_000);
    expect(drained).toEqual([handle]);
    expect(broker.registrySize()).toBe(0);
  });

  it("ack() removes the handle from the broker registry", async () => {
    const redis = new FakeRedisClient();
    redis.connected = true;

    const adapter = new QueueDispatchAdapter({
      redisClient: redis as never,
      broker,
    });

    const handle = randomUUID();
    const nonce = randomUUID();
    await adapter.submit(makeInput(handle, callbackUrl, nonce, "T7-dec-A4"));
    await postCallback(callbackUrl, handle, nonce, "in_review");
    await drainN(broker, 1, 5_000);

    await adapter.ack(handle);
    expect(broker.registrySize()).toBe(0);
    expect(broker.queueDepth()).toBe(0);
  });
});

// ── B. Concurrent coexistence — two profile instances ─────────────────────────

describe("B. Concurrent coexistence — two independent profiles", () => {
  let brokerA: InMemoryBrokerAdapter;
  let brokerB: InMemoryBrokerAdapter;

  beforeEach(async () => {
    brokerA = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    brokerB = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    await brokerA.start();
    await brokerB.start();
  });

  afterEach(async () => {
    await brokerA.stop();
    await brokerB.stop();
  });

  it("two QueueDispatchAdapters with separate Redis clients and brokers do not share state", async () => {
    const redisA = new FakeRedisClient();
    const redisB = new FakeRedisClient();
    redisA.connected = true;
    redisB.connected = true;

    const adapterA = new QueueDispatchAdapter({
      redisClient: redisA as never,
      broker: brokerA,
    });
    const adapterB = new QueueDispatchAdapter({
      redisClient: redisB as never,
      broker: brokerB,
    });

    const handleA = randomUUID();
    const handleB = randomUUID();
    expect(handleA).not.toBe(handleB);

    const nonceA = randomUUID();
    const nonceB = randomUUID();

    await adapterA.submit(makeInput(handleA, brokerA.getCallbackUrl()!, nonceA, "T7-B-1"));
    await adapterB.submit(makeInput(handleB, brokerB.getCallbackUrl()!, nonceB, "T7-B-2"));

    // Each broker has exactly one registered handle — no cross-contamination.
    expect(brokerA.registrySize()).toBe(1);
    expect(brokerB.registrySize()).toBe(1);

    // Each Redis has exactly one stream entry.
    expect(redisA.allEntries(DISPATCH_STREAM_KEY)).toHaveLength(1);
    expect(redisB.allEntries(DISPATCH_STREAM_KEY)).toHaveLength(1);

    // A's stream entry references A's handle only.
    const entryA = redisA.lastEntry(DISPATCH_STREAM_KEY)!;
    expect(entryA.fields.handle).toBe(handleA);

    // B's stream entry references B's handle only.
    const entryB = redisB.lastEntry(DISPATCH_STREAM_KEY)!;
    expect(entryB.fields.handle).toBe(handleB);
  });

  it("callbacks to broker A do not appear in broker B (no handle-space collision)", async () => {
    const redisA = new FakeRedisClient();
    const redisB = new FakeRedisClient();
    redisA.connected = true;
    redisB.connected = true;

    const adapterA = new QueueDispatchAdapter({ redisClient: redisA as never, broker: brokerA });
    const adapterB = new QueueDispatchAdapter({ redisClient: redisB as never, broker: brokerB });

    const handleA = randomUUID();
    const handleB = randomUUID();
    const nonceA = randomUUID();
    const nonceB = randomUUID();

    await adapterA.submit(makeInput(handleA, brokerA.getCallbackUrl()!, nonceA, "T7-B-3a"));
    await adapterB.submit(makeInput(handleB, brokerB.getCallbackUrl()!, nonceB, "T7-B-3b"));

    // Post callback to broker A's endpoint only.
    await postCallback(brokerA.getCallbackUrl()!, handleA, nonceA, "in_review");

    // Broker A has one completion; broker B has none.
    const drainedA = await drainN(brokerA, 1, 3_000);
    expect(drainedA).toHaveLength(1);
    expect(drainedA[0]).toBe(handleA);

    const drainedB = await drainN(brokerB, 1, 500);
    expect(drainedB).toHaveLength(0);
  });

  it("handles from the two profiles are UUID-unique (no collisions)", () => {
    const handles = new Set(Array.from({ length: 20 }, () => randomUUID()));
    expect(handles.size).toBe(20);
  });
});

// ── C. No credentials in the dispatch stream ──────────────────────────────────

describe("C. No credentials in the dispatch stream", () => {
  it("DispatchJob fields contain no secret values from the input", async () => {
    const broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    await broker.start();

    try {
      const redis = new FakeRedisClient();
      redis.connected = true;

      const adapter = new QueueDispatchAdapter({
        redisClient: redis as never,
        broker,
      });

      const handle = randomUUID();
      const nonce = randomUUID();
      const SECRET_SSH = "[REDACTED:ssh-private-key]";
      const SECRET_GH = "ghp_supersecrettoken";

      await adapter.submit({
        ...makeInput(handle, broker.getCallbackUrl()!, nonce, "T7-C-1"),
        sshPrivateKey: SECRET_SSH,
        githubToken: SECRET_GH,
      });

      const entry = redis.lastEntry(DISPATCH_STREAM_KEY)!;
      const allValues = Object.values(entry.fields).join(" ");
      expect(allValues).not.toContain(SECRET_SSH);
      expect(allValues).not.toContain(SECRET_GH);
      expect(allValues).not.toContain("supersecret");
    } finally {
      await broker.stop();
    }
  });

  it("DispatchJob includes all required non-secret fields", async () => {
    const broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    await broker.start();

    try {
      const redis = new FakeRedisClient();
      redis.connected = true;
      const adapter = new QueueDispatchAdapter({ redisClient: redis as never, broker });
      const handle = randomUUID();
      const nonce = randomUUID();
      await adapter.submit(makeInput(handle, broker.getCallbackUrl()!, nonce, "T7-C-2"));

      const entry = redis.lastEntry(DISPATCH_STREAM_KEY)!;
      const { fields } = entry;

      expect(fields.handle).toBe(handle);
      expect(fields.nonce).toBe(nonce);
      expect(fields.task_id).toBe("T7-C-2");
      expect(fields.feature_id).toBe("standalone-executor-hardening");
      expect(fields.callback_url).toContain("/callback");
      expect(fields.enqueued_at).toBeDefined();
    } finally {
      await broker.stop();
    }
  });
});

// ── D. Reconciler: lost dispatch → re-enqueue ≤ N → blocked ─────────────────

describe("D. Reconciler: lost dispatch — re-enqueue then blocked", () => {
  let submitCalls: Array<{ handle: string; taskId: string }>;
  let registerCalls: Array<{ handle: string; nonce: string }>;

  class CapturingExecutor {
    async submit(input: { handle: string; taskId: string; [k: string]: unknown }) {
      submitCalls.push({ handle: input.handle, taskId: input.taskId });
      return input.handle;
    }
    async readResult(_h: string) { return { terminal_status: "failed" as const, blocked_reason: "handle_not_found" }; }
    async ack(_h: string) { /* no-op */ }
  }

  class CapturingBroker {
    async register(handle: string, nonce: string, _meta: unknown) {
      registerCalls.push({ handle, nonce });
    }
    async ack(_h: string) { /* no-op */ }
    async nack(_h: string) { /* no-op */ }
    async listCompleted() { return []; }
    getCallbackUrl() { return "http://broker:7000/callback"; }
    inFlightCount() { return 0; }
    registrySize() { return 0; }
    start() { return Promise.resolve(7000); }
    stop() { return Promise.resolve(); }
  }

  beforeEach(() => {
    submitCalls = [];
    registerCalls = [];
    process.env.EXECUTION_DEADLINE_MS = "1"; // 1ms — everything is "stuck"
    process.env.DISPATCH_RECONCILE_MAX_RETRIES = "2";
  });

  afterEach(() => {
    delete process.env.EXECUTION_DEADLINE_MS;
    delete process.env.DISPATCH_RECONCILE_MAX_RETRIES;
  });

  it("re-enqueues a stuck task with a stale execution_handle", async () => {
    const wsRoot = makeTmpDir("reconciler-stuck-");
    makeWorkspace(wsRoot, "my-feature", {
      id: "T1",
      status: "in_progress",
      execution_handle: "handle-stuck",
      execution: {
        actor_type: "agent",
        last_updated_by: "test@test.com",
        last_updated_at: new Date(Date.now() - 10_000).toISOString(),
      },
    });

    const emit = (_e: Record<string, unknown>) => { /* no-op */ };

    try {
      await runDispatchReconciler({
        workspaceRoots: [wsRoot],
        executor: new CapturingExecutor() as never,
        broker: new CapturingBroker() as never,
        workspacesDir: "/workspaces",
        callbackUrl: "http://broker:7000/callback",
        gitAuthorEmail: "test@test.com",
        emit,
      });
    } catch {
      // appendLogEntry may throw (no real git) — that's acceptable here.
    }

    // broker.register must be called with the stale handle before re-submit.
    const reg = registerCalls.find((r) => r.handle === "handle-stuck");
    expect(reg).toBeDefined();

    // executor.submit must be called with the stale handle.
    const sub = submitCalls.find((s) => s.handle === "handle-stuck");
    expect(sub).toBeDefined();
    expect(sub!.taskId).toBe("T1");
  });

  it("does NOT re-enqueue a task with a fresh execution_handle within the deadline", async () => {
    process.env.EXECUTION_DEADLINE_MS = "999999999"; // far future

    const wsRoot = makeTmpDir("reconciler-fresh-");
    makeWorkspace(wsRoot, "my-feature", {
      id: "T2",
      status: "in_progress",
      execution_handle: "handle-fresh",
      execution: {
        actor_type: "agent",
        last_updated_by: "test@test.com",
        last_updated_at: new Date().toISOString(),
      },
    });

    const emit = (_e: Record<string, unknown>) => { /* no-op */ };

    const result = await runDispatchReconciler({
      workspaceRoots: [wsRoot],
      executor: new CapturingExecutor() as never,
      broker: new CapturingBroker() as never,
      workspacesDir: "/workspaces",
      callbackUrl: "http://broker:7000/callback",
      gitAuthorEmail: "test@test.com",
      emit,
    });

    expect(result.reEnqueued).toBe(0);
    expect(result.blocked).toBe(0);
    expect(submitCalls).toHaveLength(0);
  });

  it("transitions to blocked after MAX_RETRIES re-enqueue entries in the log", async () => {
    const wsRoot = makeTmpDir("reconciler-maxretries-");
    // Task already has MAX_RETRIES=2 reconciler_reenqueued log entries.
    makeWorkspace(wsRoot, "my-feature", {
      id: "T3",
      status: "in_progress",
      execution_handle: "handle-maxed",
      execution: {
        actor_type: "agent",
        last_updated_by: "test@test.com",
        last_updated_at: new Date(Date.now() - 10_000).toISOString(),
      },
      log: [
        { action: "reconciler_reenqueued", by: "test@test.com", at: new Date().toISOString(), handle: "handle-maxed" },
        { action: "reconciler_reenqueued", by: "test@test.com", at: new Date().toISOString(), handle: "handle-maxed" },
      ],
    });

    const emit = (_e: Record<string, unknown>) => { /* no-op */ };
    let blockedEventEmitted = false;
    const trackEmit = (e: Record<string, unknown>) => {
      if (e.type === "reconciler_task_blocked") blockedEventEmitted = true;
    };

    try {
      await runDispatchReconciler({
        workspaceRoots: [wsRoot],
        executor: new CapturingExecutor() as never,
        broker: new CapturingBroker() as never,
        workspacesDir: "/workspaces",
        callbackUrl: "http://broker:7000/callback",
        gitAuthorEmail: "test@test.com",
        emit: trackEmit,
      });
    } catch {
      /* git ops may fail in test context */
    }

    // Should NOT re-enqueue — retries exhausted.
    expect(submitCalls).toHaveLength(0);
    expect(registerCalls).toHaveLength(0);
  });

  it("does not re-enqueue a task with no execution_handle (bundled path)", async () => {
    const wsRoot = makeTmpDir("reconciler-no-handle-");
    makeWorkspace(wsRoot, "my-feature", {
      id: "T4",
      status: "in_progress",
      execution_handle: undefined, // no handle — bundled path
      execution: {
        actor_type: "agent",
        last_updated_by: "test@test.com",
        last_updated_at: new Date(Date.now() - 10_000).toISOString(),
      },
    });

    const emit = (_e: Record<string, unknown>) => { /* no-op */ };

    const result = await runDispatchReconciler({
      workspaceRoots: [wsRoot],
      executor: new CapturingExecutor() as never,
      broker: new CapturingBroker() as never,
      workspacesDir: "/workspaces",
      callbackUrl: "http://broker:7000/callback",
      gitAuthorEmail: "test@test.com",
      emit,
    });

    expect(result.reEnqueued).toBe(0);
    expect(submitCalls).toHaveLength(0);
  });
});

// ── E. Unprivileged orchestrator assertion ────────────────────────────────────

describe("E. Unprivileged orchestrator — local-docker profile", () => {
  it("createLocalDockerProfile returns a QueueDispatchAdapter as executor (not DockerRunAdapter)", () => {
    const bundle = createLocalDockerProfile({
      gitAuthorEmail: "test@test.com",
      brokerUrl: "http://broker:7000",
      redisUrl: "redis://redis:6379",
    });

    // The executor must be a QueueDispatchAdapter (XADD-only — no docker run).
    expect(bundle.executor).toBeInstanceOf(QueueDispatchAdapter);

    // Cleanup the owned Redis client (avoids dangling connection attempt).
    bundle.executor.close().catch(() => { /* best-effort */ });
  });

  it("QueueDispatchAdapter has no spawn method — it cannot directly run containers", () => {
    const adapter = new QueueDispatchAdapter({ redisUrl: "redis://localhost:6379" });

    // The adapter satisfies ExecutorPort.submit() (XADD) and ack(), nothing more.
    expect(typeof adapter.submit).toBe("function");
    expect(typeof adapter.ack).toBe("function");
    expect(typeof adapter.readResult).toBe("function");

    // No docker-specific methods — no spawn privilege.
    expect("spawn" in adapter).toBe(false);
    expect("dockerBin" in adapter).toBe(false);
    expect("spawnContainer" in adapter).toBe(false);

    adapter.close().catch(() => { /* best-effort */ });
  });

  it("local-docker profile bundle does not expose a socket path or credential injection", () => {
    const bundle = createLocalDockerProfile({
      gitAuthorEmail: "test@test.com",
      brokerUrl: "http://broker:7000",
    });

    // The bundle adapters must not expose Docker socket paths.
    const bundleStr = JSON.stringify(bundle, (_key, val) =>
      typeof val === "function" ? "[Function]" : val,
    );
    expect(bundleStr).not.toContain("/var/run/docker.sock");
    expect(bundleStr).not.toContain("dockerSocket");

    bundle.executor.close().catch(() => { /* best-effort */ });
  });
});

// ── F. Multi-task decoupled flow — M submissions, all drain ──────────────────

describe("F. Multiple concurrent submissions drain correctly (M:N property)", () => {
  it("3 independent task submissions drain exactly 3 completions", async () => {
    const broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    await broker.start();
    const callbackUrl = broker.getCallbackUrl()!;

    try {
      const redis = new FakeRedisClient();
      redis.connected = true;

      const adapter = new QueueDispatchAdapter({ redisClient: redis as never, broker });

      const tasks = ["T7-F-1", "T7-F-2", "T7-F-3"];
      const submitted: Array<{ handle: string; nonce: string }> = [];

      for (const taskId of tasks) {
        const handle = randomUUID();
        const nonce = randomUUID();
        await adapter.submit(makeInput(handle, callbackUrl, nonce, taskId));
        submitted.push({ handle, nonce });
      }

      expect(redis.allEntries(DISPATCH_STREAM_KEY)).toHaveLength(3);
      expect(broker.registrySize()).toBe(3);

      // Simulate all 3 runners posting callbacks.
      for (const { handle, nonce } of submitted) {
        await postCallback(callbackUrl, handle, nonce, "in_review");
      }

      const drained = await drainN(broker, 3, 5_000);
      expect(drained).toHaveLength(3);
      expect(broker.registrySize()).toBe(0);
      expect(broker.queueDepth()).toBe(0);

      const drainedSet = new Set(drained);
      for (const { handle } of submitted) {
        expect(drainedSet.has(handle)).toBe(true);
      }
    } finally {
      await broker.stop();
    }
  });
});

